/**
 * Admin / host preview protocol.
 *
 * Enable with `?zs_preview=1` (required for any override).
 * Force a variant with `zs_exp` + `zs_variant` query params, and/or a
 * `#zs_preview=<base64url-json>` hash payload, and/or a postMessage from
 * a parent frame (for live draft content while editing in admin).
 */

export const PREVIEW_QUERY_FLAG = "zs_preview";
export const PREVIEW_EXP_PARAM = "zs_exp";
export const PREVIEW_VARIANT_PARAM = "zs_variant";
export const PREVIEW_HASH_KEY = "zs_preview";
export const PREVIEW_MESSAGE_TYPE = "ziffsplit:set-preview";
export const PREVIEW_CHANGE_EVENT = "ziffsplit:preview-change";

export type PreviewOverride = {
  experimentKey: string;
  variantKey: string;
  /** When set, getContent() returns this instead of published authored content. */
  authoredContent?: string;
};

type PreviewMessage = {
  type: typeof PREVIEW_MESSAGE_TYPE;
  experimentKey: string;
  variantKey: string;
  authoredContent?: string;
};

function base64UrlEncode(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlDecode(encoded: string): string {
  const padded = encoded.replace(/-/g, "+").replace(/_/g, "/");
  const pad = padded.length % 4 === 0 ? "" : "=".repeat(4 - (padded.length % 4));
  const binary = atob(padded + pad);
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

export function encodePreviewHash(override: PreviewOverride): string {
  return base64UrlEncode(JSON.stringify(override));
}

export function decodePreviewHash(encoded: string): PreviewOverride | null {
  try {
    const parsed = JSON.parse(base64UrlDecode(encoded)) as Partial<PreviewOverride>;
    if (
      typeof parsed.experimentKey !== "string" ||
      typeof parsed.variantKey !== "string" ||
      !parsed.experimentKey ||
      !parsed.variantKey
    ) {
      return null;
    }
    return {
      experimentKey: parsed.experimentKey,
      variantKey: parsed.variantKey,
      authoredContent:
        typeof parsed.authoredContent === "string" ? parsed.authoredContent : undefined,
    };
  } catch {
    return null;
  }
}

export function isPreviewMode(
  search = typeof globalThis !== "undefined" && "location" in globalThis
    ? String((globalThis as { location?: { search?: string } }).location?.search ?? "")
    : "",
): boolean {
  try {
    return new URLSearchParams(search).get(PREVIEW_QUERY_FLAG) === "1";
  } catch {
    return false;
  }
}

export function readPreviewFromUrl(
  search = typeof globalThis !== "undefined" && "location" in globalThis
    ? String((globalThis as { location?: { search?: string } }).location?.search ?? "")
    : "",
  hash = typeof globalThis !== "undefined" && "location" in globalThis
    ? String((globalThis as { location?: { hash?: string } }).location?.hash ?? "")
    : "",
): PreviewOverride | null {
  if (!isPreviewMode(search)) return null;

  const hashMatch = hash.match(new RegExp(`(?:^[#&]|[#&])${PREVIEW_HASH_KEY}=([^&]+)`));
  if (hashMatch?.[1]) {
    const fromHash = decodePreviewHash(decodeURIComponent(hashMatch[1]));
    if (fromHash) return fromHash;
  }

  try {
    const params = new URLSearchParams(search);
    const experimentKey = params.get(PREVIEW_EXP_PARAM);
    const variantKey = params.get(PREVIEW_VARIANT_PARAM);
    if (experimentKey && variantKey) {
      return { experimentKey, variantKey };
    }
  } catch {
    // ignore
  }
  return null;
}

/** Build a preview URL for embedding / opening a host page. */
export function buildPreviewUrl(
  pageUrl: string,
  override: PreviewOverride,
  options?: { includeContentInHash?: boolean },
): string {
  const base =
    typeof globalThis !== "undefined" && "location" in globalThis
      ? (globalThis as { location?: { href?: string } }).location?.href
      : undefined;
  const url = new URL(pageUrl, base);
  url.searchParams.set(PREVIEW_QUERY_FLAG, "1");
  url.searchParams.set(PREVIEW_EXP_PARAM, override.experimentKey);
  url.searchParams.set(PREVIEW_VARIANT_PARAM, override.variantKey);

  const includeContent = options?.includeContentInHash !== false;
  if (includeContent && override.authoredContent !== undefined) {
    const encoded = encodePreviewHash(override);
    // Keep URLs usable; fall back to query-only force when payload is huge.
    if (encoded.length < 6000) {
      url.hash = `${PREVIEW_HASH_KEY}=${encoded}`;
    } else {
      url.hash = "";
    }
  } else {
    url.hash = "";
  }
  return url.toString();
}

export function postPreviewOverride(
  target: Window,
  override: PreviewOverride,
  targetOrigin = "*",
): void {
  const message: PreviewMessage = {
    type: PREVIEW_MESSAGE_TYPE,
    experimentKey: override.experimentKey,
    variantKey: override.variantKey,
    authoredContent: override.authoredContent,
  };
  target.postMessage(message, targetOrigin);
}

export function dispatchPreviewChange(override: PreviewOverride | null): void {
  if (typeof window === "undefined") return;
  window.dispatchEvent(
    new CustomEvent(PREVIEW_CHANGE_EVENT, { detail: override }),
  );
}

export function parsePreviewMessage(data: unknown): PreviewOverride | null {
  if (!data || typeof data !== "object") return null;
  const msg = data as Partial<PreviewMessage>;
  if (msg.type !== PREVIEW_MESSAGE_TYPE) return null;
  if (typeof msg.experimentKey !== "string" || typeof msg.variantKey !== "string") {
    return null;
  }
  if (!msg.experimentKey || !msg.variantKey) return null;
  return {
    experimentKey: msg.experimentKey,
    variantKey: msg.variantKey,
    authoredContent:
      typeof msg.authoredContent === "string" ? msg.authoredContent : undefined,
  };
}
