export type TargetingOperator = "eq" | "neq" | "in" | "contains" | "gt" | "lt";

export interface TargetingRule {
  attribute?: string;
  op?: TargetingOperator;
  value?: unknown;
  and?: TargetingRule[];
  or?: TargetingRule[];
}

function compare(op: TargetingOperator, left: unknown, right: unknown): boolean {
  switch (op) {
    case "eq":
      return left === right;
    case "neq":
      return left !== right;
    case "in":
      return Array.isArray(right) && right.includes(left);
    case "contains":
      return typeof left === "string" && typeof right === "string" && left.includes(right);
    case "gt":
      return typeof left === "number" && typeof right === "number" && left > right;
    case "lt":
      return typeof left === "number" && typeof right === "number" && left < right;
    default:
      return false;
  }
}

export function evaluateRules(
  rules: unknown[] | undefined,
  attributes: Record<string, unknown>,
): boolean {
  if (!rules || rules.length === 0) return true;

  return rules.every((raw) => {
    const rule = raw as TargetingRule;
    if (rule.and) return evaluateRules(rule.and, attributes);
    if (rule.or) return rule.or.some((r) => evaluateRules([r], attributes));
    if (!rule.attribute || !rule.op) return true;
    return compare(rule.op, attributes[rule.attribute], rule.value);
  });
}
