import type { Assignment, DomRunWhen, ExperimentConfig } from "./types.js";

export function urlMatchesPattern(href: string, pattern: string): boolean {
  const trimmed = pattern.trim();
  if (!trimmed) return false;
  try {
    return new RegExp(trimmed).test(href);
  } catch {
    return false;
  }
}

export function currentHref(): string {
  if (typeof location === "undefined") return "";
  return location.href;
}

/** Run authored JS in page context. Errors are swallowed so one bad script does not break the host. */
export function runDomScript(script: string, meta: { experimentKey: string; variantKey: string }) {
  if (typeof document === "undefined") return;
  try {
    // eslint-disable-next-line no-new-func
    const fn = new Function(
      "experimentKey",
      "variantKey",
      `"use strict";\n${script}`,
    );
    fn(meta.experimentKey, meta.variantKey);
  } catch (err) {
    console.error("[ziffsplit] dom script failed", meta, err);
  }
}

export function waitForDomMoment(
  when: DomRunWhen,
  run: () => void,
): () => void {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return () => undefined;
  }

  let cancelled = false;
  const safeRun = () => {
    if (!cancelled) run();
  };

  if (when === "load") {
    if (document.readyState === "complete") {
      safeRun();
    } else {
      window.addEventListener("load", safeRun, { once: true });
      return () => {
        cancelled = true;
        window.removeEventListener("load", safeRun);
      };
    }
    return () => {
      cancelled = true;
    };
  }

  // domcontentloaded + navigation: wait for interactive DOM first
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", safeRun, { once: true });
    return () => {
      cancelled = true;
      document.removeEventListener("DOMContentLoaded", safeRun);
    };
  }

  safeRun();
  return () => {
    cancelled = true;
  };
}

type HistoryMethod = typeof history.pushState;

export function installNavigationListener(onNavigate: () => void): () => void {
  if (typeof window === "undefined" || typeof history === "undefined") {
    return () => undefined;
  }

  const wrap = (original: HistoryMethod): HistoryMethod =>
    function (this: History, ...args: Parameters<HistoryMethod>) {
      const result = original.apply(this, args);
      onNavigate();
      return result;
    };

  const originalPush = history.pushState.bind(history);
  const originalReplace = history.replaceState.bind(history);
  history.pushState = wrap(originalPush);
  history.replaceState = wrap(originalReplace);
  window.addEventListener("popstate", onNavigate);
  window.addEventListener("hashchange", onNavigate);

  return () => {
    history.pushState = originalPush;
    history.replaceState = originalReplace;
    window.removeEventListener("popstate", onNavigate);
    window.removeEventListener("hashchange", onNavigate);
  };
}

export function isDomExperiment(exp: ExperimentConfig): boolean {
  return exp.deliveryMode === "dom";
}

export function assignmentScript(assignment: Assignment): string | null {
  if (assignment.deliveryMode !== "dom") return null;
  const script = assignment.authoredContent?.trim();
  return script || null;
}
