export type DeviceType = "mobile" | "tablet" | "desktop";

export type BrowserId =
  | "chrome"
  | "firefox"
  | "safari"
  | "edge"
  | "opera"
  | "samsung"
  | "other";

/** Best-effort device class from a user-agent string. */
export function detectDeviceType(ua: string): DeviceType {
  if (/iPad|Tablet|(Android(?!.*Mobile))/i.test(ua)) return "tablet";
  if (/Mobi|iPhone|iPod|Android.*Mobile|webOS|BlackBerry|IEMobile|Opera Mini/i.test(ua)) {
    return "mobile";
  }
  return "desktop";
}

/**
 * Best-effort browser id from a user-agent string.
 * Order matters (Edge/Opera/Samsung include Chrome tokens).
 */
export function detectBrowser(ua: string): BrowserId {
  if (/Edg(?:e|A|iOS)?\//i.test(ua)) return "edge";
  if (/OPR\/|Opera/i.test(ua)) return "opera";
  if (/SamsungBrowser/i.test(ua)) return "samsung";
  if (/Firefox\//i.test(ua)) return "firefox";
  if (/Chrome\//i.test(ua) || /CriOS\//i.test(ua)) return "chrome";
  if (/Safari\//i.test(ua)) return "safari";
  return "other";
}

export function clientEnvironmentAttributes(
  ua = typeof navigator !== "undefined" ? navigator.userAgent : "",
): { deviceType: DeviceType; browser: BrowserId } {
  return {
    deviceType: detectDeviceType(ua),
    browser: detectBrowser(ua),
  };
}
